 const mirror=new T.MeshStandardMaterial({name:'Gerahmte Spiegel im Fitnessstudio',color:'#b8c9c5',metalness:1,roughness:.065});
 const q=new Kit(g);
 const width=1.50,half=width/2,entryZ=SPA_LINK.spaZ,entryX=SPA_LINK.spaX-.095,minZ=-10.9,maxZ=entryZ+half,outline=[[-half,minZ],[half,minZ],[half,entryZ-half],[entryX,entryZ-half],[entryX,entryZ+half],[-half,entryZ+half]],shape=new T.Shape(outline.map(([x,z])=>new T.Vector2(x,-z))),geometry=new T.ExtrudeGeometry(shape,{depth:.010,bevelEnabled:false,steps:1,curveSegments:1});geometry.rotateX(-Math.PI/2);const uv=geometry.attributes.uv,pos=geometry.attributes.position;for(let i=0;i<uv.count;i++)uv.setXY(i,pos.getX(i)/.45,pos.getZ(i)/.75);
 const carpetMaterial=m.carpet.clone();carpetMaterial.name='Dicht gewebter tiefroter Premiumteppich im Fitnessstudio';carpetMaterial.bumpMap=carpetMaterial.map;carpetMaterial.bumpScale=.003;carpetMaterial.roughness=.97;const runner=q.mesh(geometry,carpetMaterial,'Einziger durchgehender Premiumteppich bis zur Fitness-Eingangstür');runner.userData={gymAisleCarpet:true,width,minZ,maxZ,plain:true,singlePiece:true,entryCarpetMaterial:'carpet',entryPoint:[entryX,entryZ],doorPoint:[SPA_LINK.spaX,entryZ],centralAxisX:0,outline,thickness:.010,thresholdGap:.095};

 // Continuous stone circulation separates the three quiet training zones.
 const zone=(name,x,z,w,d)=>{const f=q.mesh(new T.BoxGeometry(w,.018,d),floor,name);f.position.set(x,.009,z);f.userData={gymFloorZone:true,width:w,depth:d};};
 zone('Sportboden – Cardio West',-3.8,-8.65,5.5,5.1);zone('Sportboden – Cardio Ost',3.8,-8.65,5.5,5.1);
 zone('Sportboden – Krafttraining West',-3.8,2.025,5.5,14.25);zone('Sportboden – Krafttraining Ost',3.8,3.0,5.5,15.0);zone('Sportboden – Mobility und Yoga',-3.7,13.8,5.4,4.0);
 // Slatted feature partitions are wholly interior, in front of existing glazing.
 for(const x of [-6.55,6.38])for(const z of [1.0,7.8]){q.box(m.stone,x,1.30,z,.13,2.60,2.45);const p=q.mesh(new T.PlaneGeometry(2.20,2.13),mirror,'Großer gefasster Trainingsspiegel');p.rotation.y=x<0?Math.PI/2:-Math.PI/2;p.position.set(x+(x<0?.075:-.075),1.44,z);p.userData={gymMirror:true};for(const zz of [-1.14,1.14])q.box(m.frame,x+(x<0?.065:-.065),1.44,z+zz,.05,2.24,.055);for(const yy of [.34,2.54])q.box(m.frame,x+(x<0?.065:-.065),yy,z,.05,.055,2.32);}
 // Ceiling-mounted diffuse panels and fine indirect strips, below the real slab.
 for(const x of [-2.7,2.7])for(const z of [-9.2,-6.6,-3.0,1.0,4.8,8.0,12.0,15.0]){q.box(m.frame,x,2.98,z,1.1,.05,.24);q.box(m.poolWarm,x,2.945,z,1.01,.016,.18);}
 for(const x of [-6.45,6.28])q.box(m.poolWarm,x,2.66,2.2,.023,.025,25.2);
 const emblem=q.mesh(new T.PlaneGeometry(2.50,.47),m.makeSign('Lumina Leaf Hotel',{subtitle:'FITNESS & WELLNESS',width:1024,height:256,background:'#1b2927'}),'Hotelmarke im Fitnessstudio');emblem.rotation.y=Math.PI/2;emblem.position.set(-6.46,2.05,12.5);
 q.finish();
 function equipment(type,x,z,width,depth,height,build,rotation=0){const e=new T.Group();e.name=`Premium ${type}`;e.position.set(x,['Wasserstation','Mobility-Zubehör'].includes(type)?0:.018,z);e.rotation.y=rotation;e.userData={gymEquipment:type,footprint:{width,depth},height};g.add(e);const k=new Kit(e);build(k);k.finish();e.updateWorldMatrix(true,true);const inverse=e.matrixWorld.clone().invert(),bounds=new T.Box3(),matrix=new T.Matrix4();e.traverse(o=>{if(!o.isMesh)return;o.geometry.computeBoundingBox();if(o.isInstancedMesh){for(let i=0;i<o.count;i++){o.getMatrixAt(i,matrix);bounds.union(o.geometry.boundingBox.clone().applyMatrix4(inverse.clone().multiply(o.matrixWorld).multiply(matrix)));}}else bounds.union(o.geometry.boundingBox.clone().applyMatrix4(inverse.clone().multiply(o.matrixWorld)));});e.userData.modeledBounds={min:bounds.min.toArray(),max:bounds.max.toArray()};return e;}
 const feet=(k,w,d)=>{for(const x of [-w/2,w/2])for(const z of [-d/2,d/2])k.cyl(m.rubber,x,.045,z,.07,.09);};
 const display=(k,y,z,w=.48)=>{k.bevel(steel,0,y,z,w,.32,.12,.018);k.box(screen,0,y,z+.067,w-.055,.245,.010);for(let i=0;i<5;i++)k.box(i<3?m.poolGreen:m.white,-w*.30+i*w*.15,y-.07,z+.075,.032,.013,.005);};
 function treadmill(x){equipment('Laufband',x,-8.85,1.03,2.14,1.51,k=>{feet(k,.88,1.82);k.bevel(steel,0,.18,0,1.02,.22,2.05,.04);k.box(m.rubber,0,.298,.05,.78,.027,1.75);for(const x of [-.46,.46]){k.box(m.chrome,x,.307,.06,.065,.026,1.76);k.line(steel,[x,.30,-.74],[x,1.30,-.83],.049);k.line(pad,[x,1.09,-.80],[x,1.05,-.15],.036);}k.line(steel,[-.47,1.29,-.83],[.47,1.29,-.83],.048);display(k,1.33,-.80,.66);k.box(m.red,0,1.10,-.68,.055,.036,.025);});}
 for(const x of [-5.6,-3.55,-1.65])treadmill(x);
 function crossTrainer(x){equipment('Crosstrainer',x,-8.70,1.05,1.86,1.98,k=>{feet(k,.90,1.62);k.box(steel,0,.12,0,.92,.13,1.69);k.cyl(steel,0,.48,.39,.34,.20,0,Math.PI/2);k.cyl(m.chrome,0,.48,.39,.16,.23,0,Math.PI/2);for(const s of [-1,1]){const x=s*.32;k.line(steel,[x,.50,.39],[x,.22,-.57],.034);k.box(pad,x,.23,-.46,.25,.047,.48);k.line(steel,[x,.30,-.54],[x,1.62,-.66],.034);k.line(pad,[x,1.60,-.66],[x,1.94,-.56],.038);}k.line(steel,[0,.24,-.63],[0,1.45,-.64],.05);display(k,1.47,-.61,.45);});}
 for(const x of [1.95,4.0])crossTrainer(x);
 function bike(z){equipment('Indoor-Bike',5.78,z,.94,1.42,1.48,k=>{feet(k,.76,1.22);k.box(steel,0,.10,0,.82,.11,1.35);k.cyl(steel,0,.48,-.34,.34,.16,0,Math.PI/2);k.cyl(m.chrome,0,.48,-.34,.19,.19,0,Math.PI/2);k.line(steel,[0,.30,.42],[0,.68,-.34],.055);k.line(steel,[0,.40,-.10],[0,1.07,.38],.050);k.bevel(pad,0,1.12,.40,.35,.09,.29,.025);k.line(steel,[0,.45,-.42],[0,1.24,-.58],.048);k.line(pad,[-.34,1.25,-.58],[.34,1.25,-.58],.03);display(k,1.32,-.55,.34);for(const s of [-1,1]){k.line(m.chrome,[s*.13,.45,0],[s*.27,.45,-s*.12],.018);k.box(pad,s*.27,.45,-s*.12,.14,.04,.12);}});}
 bike(-8.65);bike(-5.8);
 equipment('Rudergerät',-2.85,-3.6,.82,2.75,1.15,k=>{feet(k,.67,2.5);k.box(steel,0,.14,0,.74,.10,2.64);k.box(m.chrome,0,.28,.35,.10,.07,1.86);k.bevel(pad,0,.38,.49,.43,.10,.35,.025);k.cyl(steel,0,.53,-.89,.38,.23,Math.PI/2);for(const x of [-.23,.23])k.box(pad,x,.34,-.43,.19,.10,.36);k.line(m.chrome,[0,.63,-.79],[0,.69,-.25],.012);k.line(pad,[-.27,.69,-.25],[.27,.69,-.25],.023);k.line(steel,[0,.62,-1.00],[0,.94,-1.00],.026);display(k,.98,-.98,.30);});
 function strength(type,x,z){equipment(type,x,z,1.65,2.20,2.32,k=>{feet(k,1.43,1.94);k.box(steel,0,.11,0,1.51,.14,2.08);for(const xx of [-.62,.62]){k.box(steel,xx,1.16,-.84,.085,2.22,.09);k.line(steel,[xx,2.26,-.84],[xx,1.60,.42],.045);}k.box(steel,0,2.26,-.84,1.36,.10,.18);for(let i=0;i<12;i++)k.box(pad,0,.23+i*.055,-.86,.43,.037,.30);k.box(m.chrome,0,.70,-.69,.017,1.19,.017);k.bevel(pad,0,.55,.45,.55,.10,.51,.025);k.bevel(pad,0,1.03,.11,.56,.81,.13,.025);k.line(steel,[0,.12,.46],[0,.50,.46],.048);for(const s of [-1,1]){k.line(m.chrome,[s*.42,1.64,-.02],[s*.56,1.19,.55],.029);k.line(pad,[s*.56,1.19,.55],[s*.56,1.19,.80],.027);}k.line(m.rubber,[0,2.2,-.81],[0,.87,-.81],.009);if(type==='Beinstrecker'){k.line(steel,[0,.32,.68],[0,.43,1.01],.034);k.cyl(pad,0,.46,.94,.10,.84,0,Math.PI/2);}else{k.line(m.chrome,[-.48,2.02,-.30],[.48,2.02,-.30],.023);}});}
 strength('Beinstrecker',-3.35,.25);strength('Brustpresse',3.20,-2.35);strength('Lat-Zugstation',3.20,1.45);
 equipment('Functional Trainer',-3.85,7.85,3.40,1.32,2.49,k=>{feet(k,2.96,1.17);for(const x of [-1.35,1.35]){k.box(steel,x,1.24,-.35,.18,2.45,.23);k.box(steel,x,.11,0,.63,.12,1.23);k.box(pad,x,.64,-.40,.35,1.06,.22);k.line(m.chrome,[x,.20,-.14],[x,2.35,-.14],.012);for(let j=0;j<13;j++)k.box(steel,x,.23+j*.06,-.25,.34,.038,.18);k.cyl(m.chrome,x,1.48,-.10,.09,.07,Math.PI/2);k.line(m.rubber,[x,1.48,-.10],[x*.79,1.20,.21],.01);k.line(pad,[x*.79-.12,1.20,.21],[x*.79+.12,1.20,.21],.025);}k.box(steel,0,2.40,-.35,2.80,.11,.18);k.line(m.chrome,[-.68,2.30,-.20],[.68,2.30,-.20],.025);});
 const dumbbell=(k,x,y,z,r=.08)=>{k.cyl(m.chrome,x,y,z,.019,.28,0,Math.PI/2);for(const dx of [-.14,.14])k.cyl(pad,x+dx,y,z,r,.09,0,Math.PI/2);};
 equipment('Kurzhantelständer',5.82,6.90,4.20,.76,1.03,k=>{for(const x of [-1.86,1.86]){k.line(steel,[x,.03,-.29],[x,.93,.03],.04);k.line(steel,[x,.03,.31],[x,.93,.03],.04);}for(const y of [.49,.90]){k.box(steel,0,y,0,4.07,.055,.57);for(let i=0;i<10;i++)dumbbell(k,-1.76+i*.39,y+.115,0,.065+i*.007);} },Math.PI/2);
 function bench(z){equipment('Verstellbare Trainingsbank',2.65,z,.67,1.89,1.07,k=>{feet(k,.59,1.64);k.box(steel,0,.18,0,.54,.13,1.70);k.line(steel,[0,.17,-.55],[0,.47,-.20],.04);k.line(steel,[0,.17,.60],[0,.47,.58],.04);k.bevel(pad,0,.50,.55,.55,.10,.58,.025);k.put(new T.BoxGeometry(.55,.12,1.11),pad,0,.70,-.32,1,1,1,-.42,0,0);k.line(m.chrome,[0,.24,-.66],[0,.86,-.74],.016);});}
 bench(6.0);bench(9.0);
 equipment('Kettlebell-Regal',5.75,10.06,1.56,.63,.90,k=>{k.box(steel,0,.48,0,1.50,.065,.54);for(const x of [-.65,.65])k.box(steel,x,.245,0,.06,.49,.47);for(let i=0;i<4;i++){const x=-.53+i*.35;k.ball(pad,x,.63,0,.11,.13,.11);const h=k.mesh(new T.TorusGeometry(.076,.013,6,12),m.chrome,'Griff einer Kettlebell');h.position.set(x,.78,0);}});
 for(const x of [-5.05,-2.95])equipment('Yoga-Matte',x,13.7,1.0,2.08,.10,k=>{k.bevel(m.velvet,0,.009,0,1.0,.018,2.08,.012);k.box(m.poolCushion,.23,.0505,-.65,.17,.065,.27);});
 equipment('Mobility-Zubehör',-5.1,10.50,1.35,1.10,.95,k=>{k.box(m.wood,0,.405,0,1.30,.81,.59);k.box(m.poolDeck,0,.8375,0,1.35,.055,.65);for(const x of [-.42,-.14,.14,.42])k.cyl(m.velvet,x,.53,.313,.095,.39,Math.PI/2);k.box(m.poolCushion,0,.90,0,.26,.08,.32);});
 // Towel labels reuse the exact thread texture; new gym markers are separate
