 function towels(k,x,y,z){for(let i=0;i<3;i++)k.bevel(m.poolTowel,x,y+i*.035,z,.62,.030,.37,.009);const label=k.mesh(new T.PlaneGeometry(.55,.10),m.poolEmbroidery,'Gestickter Hotelname auf Fitnesshandtuch');label.position.set(x,y+.089,z);label.rotation.x=-Math.PI/2;label.userData={gymTowel:true,hotelName:'Lumina Leaf Hotel'};}
 equipment('Handtuchschrank',-5.65,-.95,1.2,1.20,1.80,k=>{k.box(m.wood,0,.90,0,1.12,1.80,.54);k.box(pad,0,.99,.281,.96,1.54,.024);for(const y of [.28,.69,1.1,1.51]){k.box(m.poolDeck,0,y,.35,1.06,.035,.40);towels(k,0,y+.04,.34);}});
 equipment('Wasserstation',5.65,12.00,1.90,.69,1.51,k=>{k.box(m.wood,0,.54,0,1.84,1.08,.61);k.box(m.poolDeck,0,1.10,0,1.90,.06,.69);for(const x of [-.6,-.4,-.2]){k.cyl(m.glass,x,1.31,-.11,.047,.32);k.cyl(m.chrome,x,1.48,-.11,.031,.025);}for(const x of [-.6,-.4,-.2])k.cyl(m.glass,x,1.23,.16,.041,.19);towels(k,.45,1.17,0);});
